// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"runtime/debug"
	"sort"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown or Stop has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout is how long Stop waits for running jobs before cancelling them.
const stopTimeout = 30 * time.Second

// entry is a job inside the runner, with the bookkeeping Shutdown needs.
type entry struct {
	seq         uint64 // enqueue order
	job         Job
	cancel      context.CancelFunc // cancels the job's context while it runs
	interrupted bool               // Shutdown cancelled the job's context
}

// Runner runs jobs on its workers.
type Runner struct {
	workers int
	size    int // how many jobs may wait in the queue
	log     *slog.Logger

	mu       sync.Mutex
	cond     *sync.Cond // signalled when a job is queued or Shutdown starts
	queue    []*entry   // jobs not started yet, in enqueue order
	running  map[*entry]struct{}
	idle     int    // workers waiting for a job
	seq      uint64 // last enqueue sequence number
	closing  bool   // Shutdown has been called
	stopped  []*entry
	wg       sync.WaitGroup // worker goroutines
	started  bool
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	r := &Runner{workers: workers, size: queueSize, log: log, running: map[*entry]struct{}{}}
	r.cond = sync.NewCond(&r.mu)
	return r
}

// Start starts the workers.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.started {
		return
	}
	r.started = true
	r.wg.Add(r.workers)
	for i := 0; i < r.workers; i++ {
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.wg.Done()
	for {
		r.mu.Lock()
		for len(r.queue) == 0 && !r.closing {
			r.idle++
			r.cond.Wait()
			r.idle--
		}
		if r.closing {
			r.mu.Unlock()
			return
		}
		e := r.queue[0]
		r.queue = r.queue[1:]
		ctx, cancel := context.WithCancel(context.Background())
		e.cancel = cancel
		r.running[e] = struct{}{}
		r.mu.Unlock()

		panicked, err := r.call(ctx, e.job)
		cancel()
		if err != nil && !panicked {
			r.log.Error("job failed", "job", e.job.Name, "err", err)
		}

		r.mu.Lock()
		delete(r.running, e)
		if err != nil && !panicked && e.interrupted {
			r.stopped = append(r.stopped, e)
		}
		r.mu.Unlock()
	}
}

// call runs j and recovers a panic, which it logs. panicked reports whether j panicked.
func (r *Runner) call(ctx context.Context, j Job) (panicked bool, err error) {
	defer func() {
		if p := recover(); p != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", p, "stack", string(debug.Stack()))
			panicked = true
		}
	}()
	return false, j.Run(ctx)
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closing {
		return ErrStopped
	}
	// An idle worker takes a job straight away, so it adds room, as an unbuffered handoff would.
	if len(r.queue) >= r.size+r.idle {
		return ErrQueueFull
	}
	r.seq++
	r.queue = append(r.queue, &entry{seq: r.seq, job: j})
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. Enqueue returns ErrStopped from now on, and jobs that have not started are
// not started. Shutdown waits for running jobs to finish. If ctx ends first, it cancels their contexts,
// waits for them to return, and returns ctx.Err(). It returns nil when every running job finished before
// ctx ended. Calls after the first return nil at once.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.closing {
		r.mu.Unlock()
		return nil
	}
	r.closing = true
	r.cond.Broadcast()
	r.mu.Unlock()

	finished := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(finished)
	}()

	select {
	case <-finished:
		return nil
	case <-ctx.Done():
	}

	r.mu.Lock()
	idle := len(r.running) == 0
	for e := range r.running {
		e.interrupted = true
		e.cancel()
	}
	r.mu.Unlock()
	<-finished
	if idle {
		// Every job finished before ctx ended; the workers were only slow to exit.
		return nil
	}
	return ctx.Err()
}

// Stop stops the runner: it does what Shutdown does, with a 30 second timeout.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in enqueue order. Before Shutdown these are the queued
// jobs. After Shutdown they are the jobs that never started, followed by the jobs whose context Shutdown
// cancelled and that returned an error.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	out := make([]Job, 0, len(r.queue)+len(r.stopped))
	for _, e := range r.queue {
		out = append(out, e.job)
	}
	if !r.closing {
		return out
	}
	interrupted := append([]*entry(nil), r.stopped...)
	sort.Slice(interrupted, func(i, j int) bool { return interrupted[i].seq < interrupted[j].seq })
	for _, e := range interrupted {
		out = append(out, e.job)
	}
	return out
}

