func TestSecondShutdownReturnsAtOnce(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	release := make(chan struct{})
	if err := r.Enqueue(Job{Name: "held", Run: func(context.Context) error {
		<-release
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	time.Sleep(10 * time.Millisecond) // let the worker pick it up
	first := make(chan error, 1)
