cat >> internal/jobs/jobs_test.go <<'EOF'

func jobNames(jobs []Job) []string {
	var names []string
	for _, j := range jobs {
		names = append(names, j.Name)
	}
	return names
}

// waitStopped waits until Enqueue reports ErrStopped, which means Shutdown has begun.
func waitStopped(t *testing.T, r *Runner) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for {
		err := r.Enqueue(Job{Name: "probe", Run: func(context.Context) error { return nil }})
		if errors.Is(err, ErrStopped) {
			return
		}
		if time.Now().After(deadline) {
			t.Fatal("Shutdown did not start")
		}
		time.Sleep(time.Millisecond)
	}
}

func TestPendingBeforeShutdown(t *testing.T) {
	r := NewRunner(1, 10, nil) // not started
	for _, name := range []string{"a", "b"} {
		if err := r.Enqueue(Job{Name: name, Run: func(context.Context) error { return nil }}); err != nil {
			t.Fatal(err)
		}
	}
	if got := jobNames(r.Pending()); !reflect.DeepEqual(got, []string{"a", "b"}) {
		t.Fatalf("Pending = %v, want [a b]", got)
	}
}

func TestEnqueueAfterShutdownReturnsErrStopped(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	job := Job{Name: "late", Run: func(context.Context) error { return nil }}
	if err := r.Enqueue(job); !errors.Is(err, ErrStopped) {
		t.Fatalf("err = %v, want ErrStopped", err)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("Pending = %v, want none", jobNames(got))
	}
}

func TestEnqueueAfterStopReturnsErrStopped(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	r.Stop()
	job := Job{Name: "late", Run: func(context.Context) error { return nil }}
	if err := r.Enqueue(job); !errors.Is(err, ErrStopped) {
		t.Fatalf("err = %v, want ErrStopped", err)
	}
}

func TestShutdownWaitsForRunningJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	var finished atomic.Bool
	if err := r.Enqueue(Job{Name: "slow", Run: func(context.Context) error {
		time.Sleep(50 * time.Millisecond)
		finished.Store(true)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	time.Sleep(10 * time.Millisecond) // let the worker pick it up
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := r.Shutdown(ctx); err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	if !finished.Load() {
		t.Fatal("Shutdown returned before the running job finished")
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("Pending = %v, want none", jobNames(got))
	}
}

func TestShutdownDoesNotStartQueuedJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	gateStarted := make(chan struct{})
	if err := r.Enqueue(Job{Name: "gate", Run: func(ctx context.Context) error {
		close(gateStarted)
		<-ctx.Done()
		return ctx.Err()
	}}); err != nil {
		t.Fatal(err)
	}
	var ran atomic.Bool
	if err := r.Enqueue(Job{Name: "next", Run: func(context.Context) error {
		ran.Store(true)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-gateStarted
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want DeadlineExceeded", err)
	}
	if ran.Load() {
		t.Fatal("a queued job was started after Shutdown")
	}
	// Jobs that never started come first, then the cancelled job that returned an error.
	if got := jobNames(r.Pending()); !reflect.DeepEqual(got, []string{"next", "gate"}) {
		t.Fatalf("Pending = %v, want [next gate]", got)
	}
}

func TestShutdownCancelsRunningJobsAfterTimeout(t *testing.T) {
	r := NewRunner(2, 10, nil)
	r.Start()
	var cancelled atomic.Bool
	if err := r.Enqueue(Job{Name: "stuck", Run: func(ctx context.Context) error {
		<-ctx.Done()
		cancelled.Store(true)
		return ctx.Err()
	}}); err != nil {
		t.Fatal(err)
	}
	time.Sleep(10 * time.Millisecond) // let the worker pick it up
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want DeadlineExceeded", err)
	}
	if !cancelled.Load() {
		t.Fatal("running job was not cancelled")
	}
	if got := jobNames(r.Pending()); !reflect.DeepEqual(got, []string{"stuck"}) {
		t.Fatalf("Pending = %v, want [stuck]", got)
	}
}

func TestCancelledJobThatReturnsNilIsNotPending(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	if err := r.Enqueue(Job{Name: "polite", Run: func(ctx context.Context) error {
		close(started)
		<-ctx.Done()
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want DeadlineExceeded", err)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("Pending = %v, want none", jobNames(got))
	}
}

func TestPanickingJobIsRecovered(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Enqueue(Job{Name: "boom", Run: func(context.Context) error { panic("boom") }}); err != nil {
		t.Fatal(err)
	}
	ran := make(chan struct{})
	if err := r.Enqueue(Job{Name: "after", Run: func(context.Context) error {
		close(ran)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	select {
	case <-ran:
	case <-time.After(5 * time.Second):
		t.Fatal("worker did not run the job after the panic")
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("Pending = %v, want none (panicked job must not be pending)", jobNames(got))
	}
}

func TestSecondShutdownReturnsAtOnce(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	release := make(chan struct{})
	if err := r.Enqueue(Job{Name: "held", Run: func(context.Context) error {
		<-release
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	time.Sleep(10 * time.Millisecond) // let the worker pick it up
	first := make(chan error, 1)
	go func() { first <- r.Shutdown(context.Background()) }()
	waitStopped(t, r)

	returned := make(chan struct{})
	go func() {
		if err := r.Shutdown(context.Background()); err != nil {
			t.Errorf("second Shutdown = %v, want nil", err)
		}
		r.Stop()
		close(returned)
	}()
	select {
	case <-returned:
	case <-time.After(time.Second):
		t.Fatal("second Shutdown or Stop blocked while the first was waiting")
	}

	close(release)
	if err := <-first; err != nil {
		t.Fatalf("first Shutdown = %v, want nil", err)
	}
}

func TestShutdownLeavesNoGoroutines(t *testing.T) {
	before := runtime.NumGoroutine()
	r := NewRunner(4, 10, nil)
	r.Start()
	for i := 0; i < 8; i++ {
		if err := r.Enqueue(Job{Name: "quick", Run: func(context.Context) error { return nil }}); err != nil {
			t.Fatal(err)
		}
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	deadline := time.Now().Add(2 * time.Second)
	for runtime.NumGoroutine() > before {
		if time.Now().After(deadline) {
			t.Fatalf("goroutines = %d, want %d", runtime.NumGoroutine(), before)
		}
		time.Sleep(time.Millisecond)
	}
}
